use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn f(n: int) -> int
    recommends n >= 2
{
    if n >= 4 {
        n % 2
    } else {
        4 - n
    }
}

fn solve(queries: Vec<i8>) -> (results: Vec<i8>)
    requires
        forall |i: int| 0 <= i && i < queries.len() ==> queries[i] as int >= 2,
    ensures
        results.len() == queries.len(),
        forall |i: int| 0 <= i && i < queries.len() ==> 
            results[i] as int == f(queries[i] as int),
{
    let mut results_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < queries.len()
        invariant
            0 <= i <= queries.len(),
            results_vec.len() == i,
            forall |j: int| 0 <= j && j < i ==> 
                results_vec[j] as int == f(queries[j] as int),
    {
        let query = queries[i];
        let result: i8;
        
        proof {
            // The precondition ensures query >= 2
            assert(query as int >= 2);
        }
        
        if query >= 4 {
            // For n >= 4: f(n) = n % 2
            // Since i8 can represent values up to 127, and n >= 4,
            // n % 2 will be either 0 or 1, which fits in i8
            result = query % 2;
        } else {
            // For n < 4: f(n) = 4 - n
            // Since query is >= 2 and < 4, it can only be 2 or 3
            // 4 - 2 = 2, 4 - 3 = 1, both fit in i8
            result = (4 - query) as i8;
        }
        
        results_vec.push(result);
        i = i + 1;
    }
    
    results_vec
}

}
